import { Section } from "@/registry/bases/takumi/components/section/section";
import { Text } from "@/registry/bases/takumi/components/text/text";
import {
  PdfcnThemeProvider,
  usePdfcnTheme,
} from "@/registry/bases/takumi/components/theme-provider";
import {
  Document,
  Page,
  StyleSheet,
  View,
} from "@/registry/bases/takumi/lib/pdf-primitives";
import type { PdfcnTheme } from "@/registry/types/pdf-themes";

import type { EventAgendaProps, Session } from "./event-agenda.types";
import { sampleEventAgendaData } from "./event-agenda.types";

interface TimeSlotGroup {
  sessions: Session[];
  time: string;
}

const groupSessionsByTime = (sessions: Session[]): TimeSlotGroup[] => {
  const groups: TimeSlotGroup[] = [];
  const map = new Map<string, Session[]>();

  for (const session of sessions) {
    const existing = map.get(session.time);
    if (existing) {
      existing.push(session);
    } else {
      const list = [session];
      map.set(session.time, list);
      groups.push({ sessions: list, time: session.time });
    }
  }

  return groups;
};

export const EventAgendaContent = ({ data }: { data: EventAgendaProps }) => {
  const theme = usePdfcnTheme();
  const accent = data.accentColor ?? theme.colors.primary;

  const trackColorMap = new Map<string, string>();
  if (data.tracks) {
    for (const track of data.tracks) {
      trackColorMap.set(track.name.toLowerCase(), track.color);
    }
  }

  const styles = StyleSheet.create({
    breakBadge: {
      backgroundColor: theme.colors.muted,
      borderColor: theme.colors.border,
      borderRadius: 4,
      borderStyle: "solid",
      borderWidth: 1,
      paddingHorizontal: 6,
      paddingVertical: 2,
    },
    breakCard: {
      backgroundColor: theme.colors.muted,
      borderColor: theme.colors.border,
      borderRadius: 6,
      borderStyle: "dashed",
      borderWidth: 1,
      flex: 1,
      paddingHorizontal: 10,
      paddingVertical: 7,
    },
    dayBanner: {
      alignItems: "center",
      backgroundColor: theme.colors.muted,
      borderColor: theme.colors.border,
      borderRadius: 6,
      borderStyle: "solid",
      borderWidth: 1,
      flexDirection: "row",
      justifyContent: "space-between",
      marginBottom: 10,
      marginTop: 8,
      paddingHorizontal: 12,
      paddingVertical: 6,
    },
    footerContainer: {
      borderTopColor: theme.colors.border,
      borderTopStyle: "solid",
      borderTopWidth: 1,
      flexDirection: "row",
      justifyContent: "space-between",
      marginTop: "auto",
      paddingTop: 8,
    },
    headerContainer: {
      borderBottomColor: theme.colors.border,
      borderBottomStyle: "solid",
      borderBottomWidth: 1.5,
      flexDirection: "row",
      justifyContent: "space-between",
      paddingBottom: 10,
    },
    legendContainer: {
      alignItems: "center",
      flexDirection: "row",
      flexWrap: "wrap",
      gap: 6,
      marginBottom: 8,
    },
    legendDot: {
      borderRadius: 3,
      height: 7,
      marginRight: 4,
      width: 7,
    },
    legendItem: {
      alignItems: "center",
      backgroundColor: theme.colors.muted,
      borderColor: theme.colors.border,
      borderRadius: 4,
      borderStyle: "solid",
      borderWidth: 1,
      flexDirection: "row",
      paddingHorizontal: 6,
      paddingVertical: 2,
    },
    page: {
      backgroundColor: theme.colors.background,
      boxSizing: "border-box",
      minHeight: 841,
      padding: 32,
      position: "relative",
    },
    roomBadge: {
      backgroundColor: theme.colors.muted,
      borderColor: theme.colors.border,
      borderRadius: 3,
      borderStyle: "solid",
      borderWidth: 1,
      paddingHorizontal: 5,
      paddingVertical: 1,
    },
    sessionCard: {
      backgroundColor: theme.colors.background,
      borderColor: theme.colors.border,
      borderRadius: 6,
      borderStyle: "solid",
      borderWidth: 1,
      flex: 1,
      flexDirection: "column",
      paddingHorizontal: 10,
      paddingVertical: 7,
      position: "relative",
    },
    sessionsRow: {
      flex: 1,
      flexDirection: "row",
      gap: 8,
    },
    timeBox: {
      alignItems: "flex-start",
      flexDirection: "column",
      paddingTop: 2,
      width: 78,
    },
    timeSlotRow: {
      flexDirection: "row",
      marginBottom: 8,
    },
    trackBadge: {
      borderRadius: 3,
      paddingHorizontal: 6,
      paddingVertical: 1,
    },
  });

  return (
    <Document title={`${data.eventName} - Agenda`}>
      {data.days.map((day, dayIndex) => {
        const timeSlots = groupSessionsByTime(day.sessions);

        return (
          <Page key={day.label} size="A4" style={styles.page}>
            {/* Header */}
            <View style={styles.headerContainer}>
              <View style={{ flex: 1, paddingRight: 16 }}>
                <Text
                  style={{
                    color: accent,
                    fontSize: 8.5,
                    fontWeight: "bold",
                    letterSpacing: 1.2,
                    marginBottom: 2,
                    textTransform: "uppercase",
                  }}
                  noMargin
                >
                  Event Agenda
                </Text>
                <Text
                  style={{
                    fontSize: 20,
                    fontWeight: "bold",
                    lineHeight: 1.2,
                    marginBottom: 4,
                  }}
                  noMargin
                >
                  {data.eventName}
                </Text>
                <Text
                  style={{ color: theme.colors.mutedForeground, fontSize: 8.5 }}
                  noMargin
                >
                  {data.date}
                  {data.endDate ? ` – ${data.endDate}` : ""} • {data.venue}
                </Text>
              </View>

              <View
                style={{ alignItems: "flex-end", justifyContent: "center" }}
              >
                <View
                  style={{
                    backgroundColor: accent,
                    borderRadius: 4,
                    paddingHorizontal: 10,
                    paddingVertical: 4,
                  }}
                >
                  <Text
                    style={{
                      color: "#ffffff",
                      fontSize: 10,
                      fontWeight: "bold",
                      letterSpacing: 0.8,
                      textTransform: "uppercase",
                    }}
