                <Text style={{ fontSize: 11, fontWeight: "bold" }} noMargin>
                  {day.label}
                </Text>
                <Text
                  style={{ color: theme.colors.mutedForeground, fontSize: 9 }}
                  noMargin
                >
                  — {day.date}
                </Text>
              </View>

              <Text
                style={{
                  color: theme.colors.mutedForeground,
                  fontSize: 8.5,
                  fontWeight: 600,
                }}
                noMargin
              >
                Day {dayIndex + 1} of {data.days.length}
              </Text>
            </View>

            {/* Track Legend (if available) */}
            {data.tracks && data.tracks.length > 0 && (
              <View style={styles.legendContainer}>
                <Text
                  style={{
                    color: theme.colors.mutedForeground,
                    fontSize: 7.5,
                    fontWeight: "bold",
                    letterSpacing: 0.5,
                    marginRight: 4,
                    textTransform: "uppercase",
                  }}
                  noMargin
                >
                  Tracks:
                </Text>
                {data.tracks.map((track) => (
                  <View key={track.name} style={styles.legendItem}>
                    <View
                      style={[
                        styles.legendDot,
                        { backgroundColor: track.color },
                      ]}
                    />
                    <Text
                      style={{ fontSize: 7.5, fontWeight: 600 }}
                      noMargin
                    >
                      {track.name}
                    </Text>
                  </View>
                ))}
              </View>
            )}

            {/* Sessions Time Grid */}
            <Section style={{ marginTop: 2 }}>
              {timeSlots.map((slot) => {
                const isSingleBreak =
                  slot.sessions.length === 1 && slot.sessions[0].isBreak;

                return (
                  <View key={slot.time} style={styles.timeSlotRow}>
                    {/* Time Column */}
                    <View style={styles.timeBox}>
                      <Text
                        style={{
                          color: theme.colors.foreground,
                          fontSize: 9,
                          fontWeight: "bold",
                        }}
                        noMargin
                      >
                        {slot.time}
                      </Text>
                      {slot.sessions[0].endTime && (
                        <Text
                          style={{
                            color: theme.colors.mutedForeground,
                            fontSize: 7.5,
                          }}
                          noMargin
                        >
                          to {slot.sessions[0].endTime}
                        </Text>
                      )}
                    </View>

                    {/* Content Column */}
                    {isSingleBreak ? (
                      <View style={styles.breakCard}>
                        <View
                          style={{
                            alignItems: "center",
                            flexDirection: "row",
                            justifyContent: "space-between",
                          }}
                        >
                          <Text
                            style={{
                              color: theme.colors.foreground,
                              fontSize: 9.5,
                              fontWeight: "bold",
                            }}
                            noMargin
                          >
                            {slot.sessions[0].title}
                          </Text>
                          <View style={styles.breakBadge}>
                            <Text
                              style={{
                                color: theme.colors.mutedForeground,
                                fontSize: 7,
                                fontWeight: "bold",
                                letterSpacing: 0.5,
                                textTransform: "uppercase",
                              }}
                              noMargin
                            >
                              Break
                            </Text>
                          </View>
                        </View>
                        {slot.sessions[0].description && (
                          <Text
                            style={{
                              color: theme.colors.mutedForeground,
                              fontSize: 7.5,
                              marginTop: 2,
                            }}
                            noMargin
                          >
                            {slot.sessions[0].description}
                          </Text>
                        )}
                      </View>
                    ) : (
                      <View style={styles.sessionsRow}>
                        {slot.sessions.map((session, sIndex) => {
                          const trackColor = session.track
                            ? trackColorMap.get(session.track.toLowerCase())
                            : undefined;

                          return (
                            <View
                              key={`${session.title}-${sIndex}`}
                              style={[
                                styles.sessionCard,
                                trackColor
                                  ? {
                                      borderLeftColor: trackColor,
                                      borderLeftWidth: 3,
                                    }
                                  : {},
                              ]}
                            >
                              {/* Track & Room Metadata */}
                              <View
                                style={{
                                  alignItems: "center",
                                  flexDirection: "row",
                                  gap: 4,
                                  marginBottom: 3,
                                }}
                              >
                                {session.track && (
                                  <View
                                    style={[
                                      styles.trackBadge,
                                      {
                                        backgroundColor: trackColor
                                          ? `${trackColor}1A`
                                          : theme.colors.muted,
                                      },
                                    ]}
                                  >
                                    <Text
                                      style={{
                                        color:
                                          trackColor ?? theme.colors.foreground,
                                        fontSize: 7,
                                        fontWeight: "bold",
                                      }}
                                      noMargin
                                    >
                                      {session.track}
                                    </Text>
                                  </View>
                                )}
                                {session.room && (
                                  <View style={styles.roomBadge}>
                                    <Text
                                      style={{
                                        color: theme.colors.mutedForeground,
                                        fontSize: 7,
                                        fontWeight: 600,
                                      }}
                                      noMargin
                                    >
                                      {session.room}
                                    </Text>
                                  </View>
                                )}
                              </View>

                              {/* Title */}
                              <Text
                                style={{
                                  fontSize: 9,
                                  fontWeight: "bold",
                                  lineHeight: 1.25,
                                }}
                                noMargin
                              >
                                {session.title}
                              </Text>

                              {/* Speaker */}
                              {session.speaker && (
                                <Text
                                  style={{
                                    color: accent,
                                    fontSize: 7.8,
                                    fontWeight: 600,
                                    marginTop: 2,
                                  }}
                                  noMargin
                                >
                                  {session.speaker}
                                </Text>
                              )}

                              {/* Description */}
                              {session.description && (
                                <Text
                                  style={{
                                    color: theme.colors.mutedForeground,
                                    fontSize: 7.2,
                                    lineHeight: 1.2,
                                    marginTop: 2,
                                  }}
                                  noMargin
                                >
                                  {session.description}
                                </Text>
                              )}
                            </View>
                          );
                        })}
                      </View>
                    )}
                  </View>
                );
              })}
            </Section>

            {/* Footer */}
            <View style={styles.footerContainer}>
              <View style={{ flexDirection: "column", gap: 1 }}>
                {data.wifiInfo && (
                  <Text
                    style={{
                      color: theme.colors.mutedForeground,
                      fontSize: 7.5,
                      fontWeight: 600,
                    }}
                    noMargin
                  >
                    Wi-Fi: {data.wifiInfo}
                  </Text>
                )}
                {data.emergencyContact && (
                  <Text
                    style={{
                      color: theme.colors.mutedForeground,
                      fontSize: 7.2,
                    }}
                    noMargin
                  >
                    {data.emergencyContact}
                  </Text>
                )}
              </View>

              <View style={{ alignItems: "flex-end" }}>
                <Text
                  style={{
                    color: theme.colors.mutedForeground,
                    fontSize: 7.5,
                    fontWeight: 600,
                  }}
                  noMargin
                >
                  Page {dayIndex + 1} of {data.days.length}
                </Text>
              </View>
            </View>
          </Page>
        );
      })}
    </Document>
  );
};

export const EventAgendaDocument = ({
  theme,
  data = sampleEventAgendaData,
}: {
  theme?: PdfcnTheme;
  data?: EventAgendaProps;
}) => (
  <PdfcnThemeProvider theme={theme}>
    <EventAgendaContent data={data} />
  </PdfcnThemeProvider>
);

export { EventAgendaDocument as EventAgenda };

