  description?: string;
  endTime?: string;
  isBreak?: boolean;
  room?: string;
  speaker?: string;
  time: string;
  title: string;
  track?: string;
}

export interface DaySchedule {
  date: string;
  label: string;
  sessions: Session[];
}

export interface Track {
